import { photos, type PhotoName } from '@/lib/photos';

// Responsive photo without an image runtime. Variants are generated by
// scripts/optimize-images.mjs; the tiny inline blur avoids an empty tile while
// the real file loads.
export function Photo({
  name,
  alt,
  sizes,
  className,
  priority = false,
}: {
  name: PhotoName;
  alt: string;
  sizes: string;
  className?: string;
  priority?: boolean;
}) {
  const meta = photos[name];
  const largest = meta.widths[meta.widths.length - 1];
  const srcSet = meta.widths.map((width) => `/img/${name}-${width}.webp ${width}w`).join(', ');

  return (
    <img
      src={`/img/${name}-${largest}.webp`}
      srcSet={srcSet}
      sizes={sizes}
      alt={alt}
      width={meta.width}
      height={meta.height}
      loading={priority ? 'eager' : 'lazy'}
      fetchPriority={priority ? 'high' : 'auto'}
      decoding="async"
      className={className}
      style={{
        backgroundColor: meta.color,
        backgroundImage: `url("${meta.blur}")`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
      }}
    />
  );
}
